const assert = require('node:assert/strict');
const { ProfileService } = require('./.build/service');
const { parseProfile } = require('./.build/parser');

// no-op empty object, null prototype input allowed
const s = new ProfileService({ displayName: 'a', tags: ['t1'] });
assert.deepEqual(s.patch({}), { displayName: 'a', tags: ['t1'] });
assert.deepEqual(s.patch(Object.assign(Object.create(null), {})), { displayName: 'a', tags: ['t1'] });

// trimming + clear + boundaries
assert.deepEqual(s.patch({ displayName: '  spaced  ' }), { displayName: 'spaced', tags: ['t1'] });
assert.deepEqual(s.patch({ displayName: null }), { displayName: null, tags: ['t1'] });
assert.deepEqual(s.patch({ tags: null }), { displayName: null, tags: [] });
assert.deepEqual(s.patch({ tags: [] }), { displayName: null, tags: [] });
assert.throws(() => s.patch({ displayName: '' }), /invalid profile/);
assert.throws(() => s.patch({ displayName: ' '.repeat(41).replace(/ /g, ' ') + 'x' }), /invalid profile/); // 41 after trim? no
assert.doesNotThrow(() => s.patch({ displayName: 'x'.repeat(40) }));
assert.throws(() => s.patch({ displayName: 'x'.repeat(41) }), /invalid profile/);
assert.throws(() => s.patch({ tags: ['a'.repeat(13)] }), /invalid profile/);
assert.doesNotThrow(() => s.patch({ tags: ['a'.repeat(12)] }));
assert.throws(() => s.patch({ tags: ['a', 'b', 'c', 'd', 'e', 'f'] }), /invalid profile/);
assert.doesNotThrow(() => s.patch({ tags: ['a', 'b', 'c', 'd', 'e'] }));
assert.throws(() => s.patch({ tags: ['a', ' a ', 'b'] }), /invalid profile/); // duplicate after trim
assert.throws(() => s.patch({ tags: [123] }), /invalid profile/); // no coercion
assert.throws(() => s.patch({ tags: [''] }), /invalid profile/);
assert.throws(() => s.patch({ tags: ['  '] }), /invalid profile/);
assert.throws(() => s.patch({ tags: 'x' }), /invalid profile/);
assert.throws(() => s.patch({ unknown: 1 }), /invalid profile/);
assert.throws(() => s.patch([]), /invalid profile/);
assert.throws(() => s.patch(null), /invalid profile/);
assert.throws(() => s.patch(42), /invalid profile/);
class NotPlain { }
assert.throws(() => s.patch(new NotPlain()), /invalid profile/);

// storage unchanged on failure; input and caller array not mutated/reused
const stored = { displayName: 'keep', tags: ['keep'] };
const svc = new ProfileService(stored);
assert.throws(() => svc.patch({ displayName: 'ok', tags: ['good', 5] }), /invalid profile/);
assert.deepEqual(svc.patch({}), stored);
const callerTags = ['x', ' x '];
const badTags = ['y', 1];
assert.throws(() => svc.patch({ tags: badTags }), /invalid profile/);
assert.deepEqual(badTags, ['y', 1]); // input untouched
const patch = parseProfile({ tags: callerTags, displayName: 'z' });
assert.deepEqual(patch, { displayName: { kind: 'set', value: 'z' }, tags: { kind: 'set', value: ['x'] } });
assert.deepEqual(callerTags, ['x', ' x ']); // caller array untouched
const applied = svc.patch({ tags: callerTags });
assert.deepEqual(applied, { displayName: 'z', tags: ['x'] });
assert.notEqual(applied.tags, callerTags); // storage does not reuse caller array
console.log('ALL CONTRACT CHECKS PASS');
EOF
